def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute path, following symlinks.

    Args:
        path: The path to resolve (absolute or relative to cwd)
        cwd: A canonical absolute path (e.g., '/home/u')
        links: A dict mapping canonical absolute paths to symlink targets

    Returns:
        The canonical absolute path, or None on error
    """

    # Limit on total symlinks followed
    max_links = 8
    links_followed = 0

    # Start with the given path; if relative, make it absolute
    if not path.startswith('/'):
        # Relative to cwd
        if cwd.endswith('/'):
            current = cwd + path
        else:
            current = cwd + '/' + path
    else:
        current = path

    # Split into components and process left to right
    components = current.split('/')

    # Build the resolved path
    resolved = []

    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if resolved:
                resolved.pop()
            # else: at root, '/' stays '/'
            continue

        # Append the component
        resolved.append(component)

        # Check if the resulting path is a symlink
        if resolved:
            current_path = '/' + '/'.join(resolved)
        else:
            current_path = '/'

        if current_path in links:
            # We hit a symlink, follow it
            links_followed += 1
            if links_followed > max_links:
                return None

            target = links[current_path]

            # Remove the last component since we're replacing it with the target
            resolved.pop()

            # If target is absolute, start fresh from root
            if target.startswith('/'):
                resolved = []
                target_components = target.split('/')
            else:
                # Target is relative to the directory containing the link
                # The link is at current_path, which is at resolved[:-1] level
                # We already popped, so resolved is the parent dir
                target_components = target.split('/')

            # Process target components
            for target_comp in target_components:
                if target_comp == '' or target_comp == '.':
                    continue

                if target_comp == '..':
                    if resolved:
                        resolved.pop()
                    continue

                resolved.append(target_comp)

                # Check if this intermediate path is also a symlink
                if resolved:
                    intermediate_path = '/' + '/'.join(resolved)
                else:
                    intermediate_path = '/'

                if intermediate_path in links:
                    # Another symlink encountered
                    links_followed += 1
                    if links_followed > max_links:
                        return None

                    next_target = links[intermediate_path]

                    # Remove the last component
                    resolved.pop()

                    # If next_target is absolute, restart from root
                    if next_target.startswith('/'):
                        resolved = []
                        next_target_components = next_target.split('/')
                    else:
                        next_target_components = next_target.split('/')

                    # Process the rest of the target
                    for next_comp in next_target_components:
                        if next_comp == '' or next_comp == '.':
                            continue

                        if next_comp == '..':
                            if resolved:
                                resolved.pop()
                            continue

                        resolved.append(next_comp)

                        # Recursively check for more symlinks (limited by max_links)
                        if resolved:
                            check_path = '/' + '/'.join(resolved)
                        else:
                            check_path = '/'

                        if check_path in links:
                            links_followed += 1
                            if links_followed > max_links:
                                return None

    # Build final result
    if resolved:
        result = '/' + '/'.join(resolved)
    else:
        result = '/'

    return result

